import {STOCKS,MARKETS,history,metrics,forecast,predictNext,orderQuote,placeOrder,maximumPayoutCents} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const dollars=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const money=c=>dollars(c/100),signed=n=>`${n>=0?'+':''}${n.toFixed(2)}%`;
const shortDate=s=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',markets:'M3 17l6-6 4 3 8-10 M15 4h6v6 M3 21h18',portfolio:'M8 7V4h8v3 M3 7h18v14H3z M3 12c6 3 12 3 18 0 M10 13v3h4v-3',research:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5',info:'M12 11v6 M12 7v.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M18 6 6 18',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',flask:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M7 15h10'};
const glyph=id=>`<svg class="glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.info}"/></svg>`;
$$('[data-glyph]').forEach(el=>el.innerHTML=glyph(el.dataset.glyph));
const colors={NVDA:['#2c3827','#c3df9d','#3c4b32'],AAPL:['#302e2b','#d9d0c5','#47423b'],MSFT:['#25303b','#a3c7e1','#35485a'],TSLA:['#3d2826','#e6aaa0','#593e38']};
const histories=Object.fromEntries(STOCKS.map(s=>[s.symbol,history(s)]));
let selected='NVDA',range=22,showForecast=true,filter='All',search='',activeMarket=MARKETS[0],side='yes',toastTimer,portfolio={cashCents:1000000,trades:[]},watchlist=STOCKS.map(s=>s.symbol),storageAvailable=true;
try{const raw=JSON.parse(localStorage.getItem('market-signal-portfolio-v1')||'null');if(raw&&Number.isSafeInteger(raw.cashCents)&&raw.cashCents>=0&&Array.isArray(raw.trades)&&raw.trades.length<10000&&raw.trades.every(t=>MARKETS.some(m=>m.id===t.marketId)&&['yes','no'].includes(t.side)&&Number.isSafeInteger(t.shares)&&t.shares>0&&Number.isSafeInteger(t.priceCents)&&t.priceCents>0&&t.priceCents<100&&t.costCents===t.shares*t.priceCents)&&raw.cashCents+raw.trades.reduce((s,t)=>s+t.costCents,0)===1000000)portfolio=raw;const w=JSON.parse(localStorage.getItem('market-signal-watch-v1')||'null');if(Array.isArray(w))watchlist=[...new Set(w.filter(s=>STOCKS.some(a=>a.symbol===s)))];}catch{storageAvailable=false;}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Changes will last for this visit only.');return false;}}
function spark(values,color='var(--green)',w=100,h=36){const min=Math.min(...values),max=Math.max(...values),span=max-min||1;return `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><path d="${values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1)*w).toFixed(1)},${(h-3-(v-min)/span*(h-6)).toFixed(1)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/></svg>`;}
function renderTickers(){ $('#ticker-grid').innerHTML=STOCKS.map(s=>{const h=histories[s.symbol],change=(h.at(-1).close/h.at(-2).close-1)*100;return `<button class="ticker-card ${s.symbol===selected?'active':''}" data-stock="${s.symbol}" aria-label="Show ${s.name} stock chart" aria-pressed="${s.symbol===selected}"><div class="ticker-top"><strong>${s.symbol}</strong><span class="ticker-company">${s.name}</span></div><div class="ticker-main"><strong>${dollars(s.price)}</strong><span class="ticker-chart">${spark(h.slice(-18).map(r=>r.close),change>=0?'#82c9a6':'#e7938e',68,24)}</span></div><div class="ticker-change ${change>=0?'positive':'negative'}">${signed(change)}<span>last session</span></div></button>`;}).join('');}
function renderWatch(){ $('#watch-count').textContent=`${watchlist.length} ${watchlist.length===1?'asset':'assets'}`;$('#watchlist').innerHTML=watchlist.length?watchlist.map(symbol=>{const s=STOCKS.find(s=>s.symbol===symbol),h=histories[symbol],change=(h.at(-1).close/h.at(-2).close-1)*100;return `<button class="watch-item ${symbol===selected?'selected':''}" data-stock="${symbol}" aria-label="Show ${s.name} stock chart"><span><strong>${symbol}</strong><small>${s.name}</small></span><span class="watch-price">${s.price.toFixed(2)}<small class="${change>=0?'positive':'negative'}" style="color:var(--${change>=0?'green':'red'})">${signed(change)}</small></span></button>`;}).join(''):'<p class="watch-empty">Select a stock and press its star to add it here.</p>';}
function selectStock(symbol){if(!STOCKS.some(s=>s.symbol===symbol))return;selected=symbol;renderTickers();renderWatch();renderChart();renderForecast();}
function renderChart(){const s=STOCKS.find(s=>s.symbol===selected),rows=histories[selected].slice(-range),future=showForecast?forecast(histories[selected]):[],last=rows.at(-1).close,change=(last/rows[0].close-1)*100;$('#chart-name').textContent=s.name;$('#chart-sector').textContent=`${s.sector} · NASDAQ`;$('#chart-badge').textContent=s.symbol==='MSFT'?'M':s.symbol==='AAPL'?'A':s.symbol==='TSLA'?'T':'N';const color=colors[s.symbol];$('#chart-badge').style.cssText=`background:${color[0]};color:${color[1]};border-color:${color[2]}`;$('#current-price').textContent=dollars(last);$('#price-change').textContent=`${signed(change)} ${change>=0?'↗':'↘'}`;$('#price-change').className=change>=0?'positive':'negative';const watching=watchlist.includes(selected);$('#watch-button').setAttribute('aria-pressed',watching);$('#watch-button').setAttribute('aria-label',`${watching?'Remove':'Add'} ${s.name} ${watching?'from':'to'} watchlist`);$('#watch-button').style.color=watching?'#c4a68a':'#888';$('#watch-button svg').style.color='inherit';$('#watch-button svg').style.fill=watching?'#a0867233':'none';
 const W=Math.max(270,$('#chart-container').clientWidth),H=$('#chart-container').clientHeight,left=4,right=75,top=24,bottom=35,plotW=W-left-right,plotH=H-top-bottom,total=rows.length+future.length,vals=[...rows.map(r=>r.close),...future.flatMap(r=>[r.low,r.high])];let min=Math.min(...vals),max=Math.max(...vals),pad=Math.max((max-min)*.15,last*.003);min-=pad;max+=pad;const x=i=>left+i/(total-1)*plotW,y=v=>top+(max-v)/(max-min)*plotH;const line=rows.map((r,i)=>`${i?'L':'M'}${x(i).toFixed(2)} ${y(r.close).toFixed(2)}`).join(' '),lastX=x(rows.length-1),lastY=y(last),chartColor=change>=0?'#82c9a6':'#e7938e';
 let svg=`<defs><linearGradient id="price-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${chartColor}" stop-opacity=".13"/><stop offset="1" stop-color="${chartColor}" stop-opacity="0"/></linearGradient></defs>`;
 for(let i=0;i<5;i++){const yy=top+i*plotH/4,v=max-i*(max-min)/4;svg+=`<line x1="${left}" x2="${W-right+8}" y1="${yy}" y2="${yy}" class="chart-grid-line"/><text x="${W-right+20}" y="${yy+4}" class="chart-label">${v.toFixed(2)}</text>`;}
 const ticks=W<500?[0,Math.round((rows.length-1)*.5),rows.length-1]:[0,Math.round((rows.length-1)*.25),Math.round((rows.length-1)*.5),Math.round((rows.length-1)*.75),rows.length-1];for(const i of [...new Set(ticks)])svg+=`<text x="${x(i)}" y="${H-8}" text-anchor="${i===0?'start':'middle'}" class="chart-x-label">${shortDate(rows[i].date)}</text>`;
 if(future.length){const points=[{median:last,low:last,high:last},...future];const band=points.map((p,i)=>`${i?'L':'M'}${x(rows.length-1+i)} ${y(p.high)}`).join(' ')+points.toReversed().map((p,i)=>`L${x(total-1-i)} ${y(p.low)}`).join(' ')+'Z';const dash=points.map((p,i)=>`${i?'L':'M'}${x(rows.length-1+i)} ${y(p.median)}`).join(' ');svg+=`<rect x="${lastX}" y="${top}" width="${plotW+left-lastX}" height="${plotH}" fill="#a08672" opacity=".035"/><path d="${band}" fill="#a08672" opacity=".14"/><line x1="${lastX}" x2="${lastX}" y1="${top}" y2="${H-bottom}" stroke="#64503f" stroke-dasharray="4 5"/><text x="${lastX+8}" y="${top+12}" fill="#bda58e" font-size="11" font-family="var(--font-text)">${W<500?'Est.':'Forecast'}</text><path d="${dash}" fill="none" stroke="#c0a083" stroke-width="2" stroke-dasharray="5 5"/><text x="${x(total-1)}" y="${H-8}" text-anchor="middle" class="chart-x-label">${shortDate(future.at(-1).date)}</text>`;}
 svg+=`<path d="${line} L${lastX} ${H-bottom} L${left} ${H-bottom} Z" fill="url(#price-fill)"/><path d="${line}" fill="none" stroke="${chartColor}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/><line x1="${left}" x2="${W-right+10}" y1="${lastY}" y2="${lastY}" stroke="${chartColor}" stroke-dasharray="3 5" opacity=".25"/><circle cx="${lastX}" cy="${lastY}" r="4" fill="${chartColor}" stroke="#171717" stroke-width="2"/><rect x="${W-right+11}" y="${lastY-11}" width="61" height="22" rx="3" fill="${chartColor}"/><text x="${W-right+41}" y="${lastY+4}" text-anchor="middle" fill="#11251b" font-family="var(--font-mono)" font-size="11">${last.toFixed(2)}</text><g id="chart-crosshair" style="display:none"><line id="crosshair-line" y1="${top}" y2="${H-bottom}" stroke="#888" stroke-dasharray="3 3"/><circle id="crosshair-dot" r="4" fill="#ddd" stroke="#171717" stroke-width="2"/></g><rect class="chart-hover-area" x="${left}" y="0" width="${plotW}" height="${H-bottom}"/>`;
 const chart=$('#price-chart');chart.setAttribute('viewBox',`0 0 ${W} ${H}`);chart.innerHTML=svg;chart.setAttribute('aria-label',`${s.name}: ${rows.length} synthetic closing prices from ${shortDate(rows[0].date)} to ${shortDate(rows.at(-1).date)}. Last close ${dollars(last)}.${showForecast?' Includes five-session forecast and approximate 90% range.':''}`);const target=chart.querySelector('.chart-hover-area');const displayPoint=ev=>{const bounds=chart.getBoundingClientRect(),mx=(ev.clientX-bounds.left)/bounds.width*W,index=Math.max(0,Math.min(total-1,Math.round((mx-left)/plotW*(total-1))));const isFuture=index>=rows.length,point=isFuture?future[index-rows.length]:rows[index],value=isFuture?point.median:point.close;const px=x(index),py=y(value);$('#crosshair-line').setAttribute('x1',px);$('#crosshair-line').setAttribute('x2',px);$('#crosshair-dot').setAttribute('cx',px);$('#crosshair-dot').setAttribute('cy',py);$('#chart-crosshair').style.display='';const tip=$('#chart-tooltip');tip.innerHTML=`<small>${shortDate(point.date)} · ${isFuture?'Forecast':'Synthetic close'}</small><strong>${dollars(value)}</strong>${isFuture?`<small>90% range ${dollars(point.low)}–${dollars(point.high)}</small>`:''}`;tip.hidden=false;tip.style.left=Math.max(0,Math.min(bounds.width-205,px/W*bounds.width-75))+'px';tip.style.top=Math.max(0,py/H*bounds.height-65)+'px';};target.addEventListener('pointermove',displayPoint);target.addEventListener('pointerleave',()=>{$('#chart-tooltip').hidden=true;$('#chart-crosshair').style.display='none';});$('.forecast-legend').hidden=!showForecast;$('.chart-footer>span').style.visibility=showForecast?'visible':'hidden';}
function renderForecast(){const rows=histories[selected],f=forecast(rows),m=metrics(rows),change=(f[0].median/rows.at(-1).close-1)*100;$('#next-price').textContent=dollars(f[0].median);$('#next-change').textContent=signed(change);$('#next-change').className=change>=0?'positive':'negative';$('#next-range').textContent=`${dollars(f[0].low)} – ${dollars(f[0].high)} range`;$('#five-price').textContent=dollars(f.at(-1).median);$('#mae').textContent=dollars(m.mae);$('#mape').textContent=m.mape.toFixed(2)+'%';$('#accuracy').textContent=m.direction.toFixed(1)+'%';$('#accuracy-bar').style.width=m.direction+'%';$('#accuracy-detail').textContent=`${m.correct} of ${m.total} prior directions · one-step backtest`;}
function marketCard(m){const isMacro=!m.symbol;return `<article class="market-card"><div class="contract-top"><span class="contract-symbol ${isMacro?'macro':''}">${m.symbol||'FED'}</span><span>${m.tag}</span></div><h3 class="contract-title"><button data-market="${m.id}" data-side="yes">${m.title}</button></h3><div class="probability-row"><div class="probability">${m.yes}%<small>chance</small></div><span class="contract-spark">${spark(m.spark,m.yes>=50?'#82c9a6':'#b99b80')}</span></div><div class="market-buttons"><button data-market="${m.id}" data-side="yes" aria-label="Buy Yes for ${m.title} at ${m.yes} cents">Yes <span>${m.yes}¢ ↗</span></button><button data-market="${m.id}" data-side="no" aria-label="Buy No for ${m.title} at ${100-m.yes} cents">No <span>${100-m.yes}¢ ↗</span></button></div><div class="contract-footer"><span>$${(m.volume/1000).toFixed(1)}k volume</span><span>${m.date.replace(' 2026','')} <span>↗</span></span></div></article>`;}
function renderMarkets(){$('#overview-markets').innerHTML=MARKETS.map(marketCard).join('');const filtered=MARKETS.filter(m=>(filter==='All'||m.category===filter)&&`${m.title} ${m.symbol||''} ${m.category}`.toLowerCase().includes(search.toLowerCase()));$('#all-markets').innerHTML=filtered.map(marketCard).join('');$('#market-empty').hidden=!!filtered.length;}
function viewFromHash(){const view=location.hash.slice(1)||'overview',valid=['overview','markets','portfolio','methodology'].includes(view)?view:'overview';$$('.dashboard-view').forEach(el=>el.hidden=el.id!==valid);$$('[data-view]').forEach(el=>{if(el.dataset.view===valid)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#breadcrumb-current').textContent=valid[0].toUpperCase()+valid.slice(1);if(valid==='portfolio')renderPortfolio();$('#sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);}
function openTrade(id,newSide='yes'){activeMarket=MARKETS.find(m=>m.id===id);if(!activeMarket)return;side=newSide;$('#trade-category').textContent=activeMarket.category+' · Event contract';$('#trade-title').textContent=activeMarket.title;$('#trade-expiry').textContent=`Resolves ${activeMarket.date} · Synthetic quote`;$('#order-error').textContent='';$('#order-amount').removeAttribute('aria-invalid');$('#trade-status').textContent='';$('#order-amount').value='100';renderQuote();$('#trade-dialog').showModal();}
function amountInCents(){const raw=$('#order-amount').value.trim();if(!/^\d+(\.\d{1,2})?$/.test(raw))return NaN;return Math.round(Number(raw)*100);}
function renderQuote(){$('#buy-yes').textContent=`Buy Yes · ${activeMarket.yes}¢`;$('#buy-no').textContent=`Buy No · ${100-activeMarket.yes}¢`;$('#buy-yes').setAttribute('aria-pressed',side==='yes');$('#buy-no').setAttribute('aria-pressed',side==='no');const amount=amountInCents(),price=side==='yes'?activeMarket.yes:100-activeMarket.yes;let q={shares:0,costCents:0,payoutCents:0};try{q=orderQuote(amount,price);}catch{}$('#order-shares').textContent=q.shares.toLocaleString()+' '+side.toUpperCase();$('#order-cost').textContent=money(q.costCents);$('#order-payout').textContent=money(q.payoutCents);$('#order-balance').textContent=money(portfolio.cashCents);}
function renderPortfolio(){const spent=portfolio.trades.reduce((a,t)=>a+t.costCents,0),payout=maximumPayoutCents(portfolio.trades);$('#portfolio-summary').innerHTML=`<div class="portfolio-stat"><span>Available paper funds</span><strong>${money(portfolio.cashCents)}</strong><small>Started with $10,000.00</small></div><div class="portfolio-stat"><span>Capital in positions</span><strong>${money(spent)}</strong><small>${portfolio.trades.length} paper ${portfolio.trades.length===1?'order':'orders'} · At entry cost</small></div><div class="portfolio-stat"><span>Maximum possible payout</span><strong>${money(payout)}</strong><small>Best outcome per event · Unsettled</small></div>`;$('#positions').innerHTML=portfolio.trades.length?`<div class="ledger-wrap"><table class="ledger"><thead><tr><th>Contract</th><th>Side</th><th>Shares</th><th>Entry</th><th>Cost</th><th>Payout if correct</th></tr></thead><tbody>${portfolio.trades.map(t=>{const m=MARKETS.find(m=>m.id===t.marketId);return `<tr><td>${m.title}<span class="position-meta">${m.date} · Unsettled</span></td><td data-label="Side"><span class="side-pill ${t.side}">${t.side==='yes'?'Yes':'No'}</span></td><td data-label="Shares">${t.shares.toLocaleString()}</td><td data-label="Entry">${t.priceCents}¢</td><td data-label="Cost">${money(t.costCents)}</td><td data-label="Payout if correct">${money(t.shares*100)}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="position-empty"><span>${glyph('portfolio')}</span><h3>Your first position starts here</h3><p>Choose a market and test your view with paper funds.</p><a class="btn btn--primary" href="#markets">Browse markets <span>↗</span></a></div>`;}
function exportData(){const header='symbol,series,date,actual_close_usd,forecast_usd,range_low_usd,range_high_usd';const records=[header];for(const s of STOCKS){const rows=histories[s.symbol],closes=rows.map(r=>r.close);rows.forEach((r,i)=>records.push([s.symbol,i>=60?'backtest':'history',r.date,r.close.toFixed(2),i>=60?predictNext(closes.slice(0,i)).toFixed(4):'','',''].join(',')));forecast(rows).forEach(f=>records.push([s.symbol,'forecast',f.date,'',f.median.toFixed(4),f.low.toFixed(4),f.high.toFixed(4)].join(',')));}const blob=new Blob(['# SYNTHETIC DEMO DATA. Not exchange prices.\r\n'+records.join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='market-signal-synthetic-prices.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Synthetic prices and forecast data exported.');}
document.addEventListener('click',ev=>{const stock=ev.target.closest('[data-stock]');if(stock){selectStock(stock.dataset.stock);if(location.hash&&location.hash!=='#overview')location.hash='overview';$('#sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}const market=ev.target.closest('[data-market]');if(market)openTrade(market.dataset.market,market.dataset.side);const period=ev.target.closest('[data-range]');if(period){range=Number(period.dataset.range);$$('[data-range]').forEach(b=>{b.classList.toggle('active',b===period);b.setAttribute('aria-pressed',b===period);});renderChart();}const category=ev.target.closest('[data-filter]');if(category){filter=category.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===category);b.setAttribute('aria-pressed',b===category);});renderMarkets();}const preset=ev.target.closest('[data-amount]');if(preset){$('#order-amount').value=preset.dataset.amount;renderQuote();}});
$('#forecast-toggle').addEventListener('change',ev=>{showForecast=ev.target.checked;renderChart();});$('#watch-button').addEventListener('click',()=>{watchlist=watchlist.includes(selected)?watchlist.filter(s=>s!==selected):STOCKS.map(s=>s.symbol).filter(s=>watchlist.includes(s)||s===selected);persist('market-signal-watch-v1',watchlist);renderWatch();renderChart();});$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',open);$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){$('#sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}});document.addEventListener('pointerdown',ev=>{if(!ev.target.closest('#sidebar')&&!ev.target.closest('#menu-toggle')){$('#sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
$('#market-search').addEventListener('input',ev=>{search=ev.target.value;renderMarkets();});$('#chart-method').addEventListener('click',()=>location.hash='methodology');$('#info-button').addEventListener('click',()=>location.hash='methodology');$('#export-button').addEventListener('click',exportData);$('#method-export').addEventListener('click',exportData);$('#close-trade').addEventListener('click',()=>$('#trade-dialog').close());$('#trade-dialog').addEventListener('click',ev=>{if(ev.target===$('#trade-dialog')){const r=$('#trade-dialog').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('#trade-dialog').close();}});$('#buy-yes').addEventListener('click',()=>{side='yes';renderQuote();});$('#buy-no').addEventListener('click',()=>{side='no';renderQuote();});$('#order-amount').addEventListener('input',()=>{renderQuote();});$('#max-amount').addEventListener('click',()=>{$('#order-amount').value=(portfolio.cashCents/100).toFixed(2);renderQuote();});$('#trade-form').addEventListener('submit',ev=>{ev.preventDefault();try{const amount=amountInCents();if(!Number.isSafeInteger(amount)||amount<=0)throw new Error('Enter a positive dollar amount with up to two decimal places.');const updated=placeOrder(portfolio,activeMarket,side,amount);portfolio=updated;persist('market-signal-portfolio-v1',portfolio);const t=portfolio.trades[0];$('#order-error').textContent='';$('#order-amount').removeAttribute('aria-invalid');$('#trade-dialog').close();renderPortfolio();toast(`Paper order placed: ${t.shares} ${side.toUpperCase()} shares for ${money(t.costCents)}.`);}catch(error){$('#order-error').textContent=error.message;$('#order-amount').setAttribute('aria-invalid','true');$('#order-amount').focus();}});$('#reset-button').addEventListener('click',()=>{portfolio={cashCents:1000000,trades:[]};persist('market-signal-portfolio-v1',portfolio);renderPortfolio();toast('Paper account reset to $10,000.00.');});
$('#sidebar-close').addEventListener('click',()=>{$('#sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');$('#menu-toggle').focus();});
window.addEventListener('hashchange',viewFromHash);renderTickers();renderWatch();renderChart();renderForecast();renderMarkets();renderPortfolio();viewFromHash();if(!storageAvailable)toast('Browser storage unavailable. This visit’s paper positions will not persist.');

let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(renderChart,120);});
